const formResponse = $input.first().json.body.form_response;

const fields = formResponse.definition?.fields || [];
const answers = formResponse.answers || [];

// Store answers by field id
const answersByFieldId = {};

for (const answer of answers) {
  const fieldId = answer.field?.id;
  let value = null;

  if ("text" in answer) value = answer.text;
  else if ("email" in answer) value = answer.email;
  else if ("number" in answer) value = answer.number;
  else if ("boolean" in answer) value = answer.boolean;
  else if ("date" in answer) value = answer.date;
  else if ("phone_number" in answer) value = answer.phone_number;
  else if ("url" in answer) value = answer.url;
  else if ("choice" in answer) value = answer.choice?.label ?? null;
  else if ("choices" in answer) value = answer.choices?.labels ?? null;
  else if ("file_url" in answer) value = answer.file_url;

  answersByFieldId[fieldId] = value;
}

// Return only question: answer
const result = {};

for (const field of fields) {
  const question = field.title;
  const fieldId = field.id;

  result[question] = Object.prototype.hasOwnProperty.call(answersByFieldId, fieldId)
    ? answersByFieldId[fieldId]
    : null;
}

return [
  {
    json: result
  }
];

